from core.parts import origin_machine


class SingleBlockerOverSortedBase:
    """Mueve desde pilas con un único bloqueador sobre una base ya ordenada."""

    name = "single_blocker_over_sorted_base"

    def __init__(self, min_sorted_base, max_top_group, prefer_taller_base):
        self.min_sorted_base = int(min_sorted_base)
        self.max_top_group = int(max_top_group)
        self.prefer_taller_base = bool(prefer_taller_base)

    def sources(self, partial, memory):
        stacks = partial.stacks
        full_count = 0
        for i in range(partial.S):
            if partial.h(i) >= partial.H:
                full_count += 1
        if full_count >= partial.S - 1:
            return []

        candidates = []
        for i, stack in enumerate(stacks):
            h = len(stack)
            if h <= 1:
                continue

            sorted_base = partial.sorted_n[i]
            if sorted_base < self.min_sorted_base:
                continue
            if sorted_base >= h:
                continue

            bad_count = h - sorted_base
            if bad_count != 1:
                continue

            top = stack[-1]
            if top > self.max_top_group:
                continue

            # Debe existir algún destino no lleno distinto de la propia pila.
            has_room_elsewhere = False
            for j in range(partial.S):
                if j != i and partial.h(j) < partial.H:
                    has_room_elsewhere = True
                    break
            if not has_room_elsewhere:
                continue

            base_top = stack[sorted_base - 1]
            gap = top - base_top

            if self.prefer_taller_base:
                key = (-sorted_base, -h, gap, top, i)
            else:
                key = (gap, top, -sorted_base, -h, i)

            candidates.append((key, i))

        candidates.sort()
        return [i for _, i in candidates]


def build_component(problem, **params):
    min_sorted_base = params.get("min_sorted_base", COMPONENT["params"]["min_sorted_base"]["default"])
    max_top_group = params.get("max_top_group", COMPONENT["params"]["max_top_group"]["default"])
    prefer_taller_base = params.get("prefer_taller_base", COMPONENT["params"]["prefer_taller_base"]["default"])
    return origin_machine(
        problem,
        SingleBlockerOverSortedBase(
            min_sorted_base=min_sorted_base,
            max_top_group=max_top_group,
            prefer_taller_base=prefer_taller_base,
        ),
    )
